int[] nums = {1, -1, 5};
int k = 5;
int best = Integer.MAX_VALUE, sum = 0, left = 0;
for (int right = 0; right < nums.length; right++) {
    sum += nums[right];
    while (sum >= k) {
        best = Math.min(best, right - left + 1);
        sum -= nums[left++];
    }
}
System.out.println(best);
